async ({ workspace: { read }, git: { status, log, tag }, shell: { execFile } }) => {
  const [skill, st, lg, tags, pkg] = await Promise.all([
    read(".pi/skills/pit-delivery/SKILL.md", { format: "raw" }),
    status(["--short", "--branch"]),
    log(["--oneline", "-15"]),
    execFile("git", ["tag", "--sort=-v:refname"]),
    read("package.json", { format: "raw" }),
  ]);
  return { skill: skill.content, st: st.stdout, lg: lg.stdout, tags: tags.stdout.split("\n").slice(0, 5), version: JSON.parse(pkg.content).version };
}
